let speed = 0.1;
this.isOn = false;

const Wheel_FL = this.getObjectByName('Wheel_FL');
const Wheel_FR = this.getObjectByName('Wheel_FR');
const Wheel_BL = this.getObjectByName('Wheel_BL');
const Wheel_BR = this.getObjectByName('Wheel_BR');
const car_lights = scene.getObjectByName('car_lights');

function update( event ) {

	if (this.isOn == true) {
		Wheel_FL.rotation.x += speed;
		Wheel_FR.rotation.x += speed;
		Wheel_BL.rotation.x += speed;
		Wheel_BR.rotation.x += speed;
	}
}

this.turnOn = function() {
	this.isOn = true;
	car_lights.visible = true;
}

this.turnOff = function() {
	this.isOn = false;
	car_lights.visible = false;
}

this.on_off = function() {
	if (this.isOn) { this.turnOff(); }
	else { this.turnOn(); }	
}
